package com.ragnarok93.bbsremix.patch

/**
 * Offline SHA-256 prefix reference fingerprints from the user's matching
 * BBS0/1/3 resources. Six columns are 70,75,80,85,90,95% respectively.
 *
 * Original source checks use complete SHA-256; this independent 128-bit
 * prefix comparison is used only for standalone Verify Output of scaled
 * resources when the original game image is not available.
 */
internal object UiScaleExpectedDigests {
    private val table: Map<String, List<String>> by lazy {
        TABLE.trim().lineSequence().associate { line ->
            val parts = line.split(':', limit = 2)
            require(parts.size == 2)
            val digests = parts[1].split(',')
            require(digests.size == 6 && digests.all { it.length == 32 })
            parts[0] to digests
        }
    }

    fun expectedPrefix(archive: String, offsetInArchive: Long, percent: Int): String? {
        if (!UiScaleSettings.isSelectable(percent) || percent == 100) return null
        return table[archive + "@" + offsetInArchive]?.get((percent - 70) / 5)
    }

    fun contains(archive: String, offsetInArchive: Long): Boolean =
        table.containsKey(archive + "@" + offsetInArchive)

    internal val profileCount: Int get() = table.size

